const KUTUP_KURAL=[
 {tr:['Taşların hareketi','Şah her yöne bir kare gider. Vezir yatay, dikey ve çapraz istediği kadar ilerler. Kale yatay ve dikey, fil çapraz gider. At "L" çizer (iki kare bir yöne, bir kare yana) ve taşların üstünden atlayabilen tek taştır. Piyon ileri gider, çapraz alır; ilk hamlesinde iki kare ilerleyebilir.'],
  en:['How the pieces move','The king moves one square in any direction. The queen moves any distance along ranks, files and diagonals. The rook moves along ranks and files, the bishop along diagonals. The knight jumps in an "L" (two squares one way, one square sideways) and is the only piece that can jump over others. Pawns move forward and capture diagonally; on their first move they may advance two squares.']},
 {tr:['Şah, mat ve pat','Şah saldırı altındaysa "şah" denir ve bu durum hemen giderilmelidir: şah kaçar, saldıran taş alınır ya da araya taş konur. Hiçbir yolla kurtulamıyorsa "mat" olur ve oyun biter. Sırası gelen oyuncunun şahı saldırı altında değilken hiç yasal hamlesi yoksa "pat" olur: oyun berabere biter.'],
  en:['Check, checkmate and stalemate','A king under attack is "in check" and the threat must be met at once: move the king, capture the attacker or block. If nothing works it is "checkmate" and the game ends. If the side to move is not in check but has no legal move, it is "stalemate": the game is a draw.']},
 {tr:['Rok','Şah ve kalenin tek hamlede yer değiştirmesidir: şah kaleye doğru iki kare gider, kale şahın üzerinden atlayıp yanına geçer. Şartlar: şah ve o kale daha önce hiç oynamamış olmalı, aradaki kareler boş olmalı, şah o an şahta olmamalı ve geçeceği ya da varacağı kare saldırı altında olmamalı.'],
  en:['Castling','The king and a rook move in a single turn: the king moves two squares towards the rook and the rook jumps over to the square beside it. Conditions: neither the king nor that rook has moved, the squares between them are empty, the king is not in check and does not pass through or land on an attacked square.']},
 {tr:['Geçerken alma (en passant)','Rakip piyon ilk hamlesinde iki kare ilerleyip senin piyonunun hemen yanına gelirse, onu sanki tek kare ilerlemiş gibi çapraz alabilirsin. Bu hak yalnızca hemen bir sonraki hamlede kullanılabilir.'],
  en:['En passant','If an enemy pawn advances two squares on its first move and lands right beside your pawn, you may capture it as if it had moved only one square. The right exists only on the very next move.']},
 {tr:['Terfi','Son sıraya ulaşan piyon aynı hamlede vezir, kale, fil ya da ata dönüşür. Çoğunlukla vezir seçilir; bazen pattan kaçınmak ya da çatal kurmak için daha küçük bir taş seçmek (alt terfi) daha iyidir.'],
  en:['Promotion','A pawn reaching the last rank becomes a queen, rook, bishop or knight on the same move. A queen is usually chosen; sometimes a smaller piece (underpromotion) is better to avoid stalemate or to fork.']},
 {tr:['Beraberlikler','Oyun berabere biter: pat olursa; aynı konum üç kez tekrar ederse; son 50 hamlede piyon oynanmamış ve taş alınmamışsa; iki tarafta da mat yapacak taş kalmamışsa (örneğin yalnız şahlar, şah ve fil, şah ve at); ya da oyuncular anlaşırsa.'],
  en:['Draws','The game is drawn by stalemate; when the same position occurs three times; when 50 moves pass without a pawn move or capture; when neither side has enough material to mate (for example bare kings, king and bishop, king and knight); or by agreement.']},
 {tr:['Süre ve saat','Süreli oyunda her oyuncunun kendi saati vardır ve yalnız kendi sırasında işler. "10+0" on dakika, "3+2" üç dakika ve her hamlede iki saniye ekleme demektir. Süresi biten oyuncu kaybeder; ancak rakibinde mat yapacak taş kalmamışsa sonuç beraberliktir.'],
  en:['Time and clocks','In timed games each player has a clock that runs only on their turn. "10+0" means ten minutes; "3+2" means three minutes plus two seconds per move. A player whose time runs out loses, unless the opponent has no material left to mate, in which case it is a draw.']},
 {tr:['Dokunulan taş oynanır','Turnuva kuralıdır: kendi taşına bilerek dokunan oyuncu, yasal bir hamlesi varsa o taşı oynamak zorundadır; rakip taşa dokunduysa onu almak zorundadır. Taşı düzeltmek için önce "düzeltiyorum" denir.'],
  en:['Touch-move','A tournament rule: a player who deliberately touches one of their own pieces must move it if it has a legal move; touching an opponent\'s piece means capturing it if possible. To adjust a piece you say "I adjust" first.']},
 {tr:['Puan (Elo)','Oyuncunun gücü bir sayıyla ölçülür. Kendinden güçlü birini yenen çok puan kazanır, zayıf birine kaybeden çok puan kaybeder. Chess64\'te çevrimiçi maçlar bu sistemle puanlanır; ilk hamleler yapılmadan biten oyun puanı değiştirmez.'],
  en:['Rating (Elo)','A player\'s strength is measured by a number. Beating a stronger player earns many points; losing to a weaker one costs many. Online games in Chess64 are rated this way; a game that ends before the first moves are played does not change the rating.']},
];
const KUTUP_VARYANT=[
 {tr:['Chess960 (Fischer Satrancı)','Arka sıradaki taşlar 960 olası dizilişten birine rastgele yerleşir; iki taraf aynı dizilişle başlar. Fil farklı renklerde, şah iki kalenin arasında kalır ve rok yine yapılabilir. Ezber açılışları işe yaramaz, oyun ilk hamleden düşünmeye başlar. Bobby Fischer 1996\'da önerdi.'],
  en:['Chess960 (Fischer Random)','The back-rank pieces are shuffled into one of 960 starting positions, the same for both sides. Bishops stay on opposite colours, the king stays between the rooks and castling still exists. Memorised openings are useless; thinking starts on move one. Proposed by Bobby Fischer in 1996.']},
 {tr:['Crazyhouse','Aldığın taş senin olur: sıran geldiğinde hamle yapmak yerine onu tahtadaki boş bir kareye koyabilirsin. Piyonlar ilk ve son sıraya konamaz. Saldırılar çok hızlı gelişir, mat temaları her yerdedir.'],
  en:['Crazyhouse','Captured pieces join your side: instead of moving you may drop one on any empty square. Pawns cannot be dropped on the first or last rank. Attacks build very fast and mating patterns are everywhere.']},
 {tr:['Bughouse (Takım satrancı)','İki tahtada dört kişi, ikişerli takım olarak oynar. Arkadaşının aldığı taşlar sana geçer ve onları kendi tahtana koyabilirsin. Hızlı ve gürültülü bir oyundur; takım arkadaşıyla konuşmak serbesttir.'],
  en:['Bughouse','Four players on two boards, in teams of two. Pieces your partner captures are passed to you and you can drop them on your board. It is fast and noisy; talking to your partner is allowed.']},
 {tr:['Tepenin Şahı (King of the Hill)','Normal kurallara ek olarak şahını tahtanın ortasındaki dört kareden birine (d4, e4, d5, e5) güvenle getiren oyunu kazanır. Şah oyunun başından itibaren aktif bir taşa dönüşür.'],
  en:['King of the Hill','Normal rules apply, but a player who safely brings the king to one of the four centre squares (d4, e4, d5, e5) wins. The king becomes an active piece from the start.']},
 {tr:['Üç Şah (Three-check)','Rakibe üç kez şah çeken kazanır; mat da geçerlidir. Açık şahlar ve sürekli şah çekmek çok değerlidir, şah güvenliği her şeyden önemlidir.'],
  en:['Three-check','Giving check three times wins; checkmate still counts too. Open kings and repeated checks are very valuable; king safety is everything.']},
 {tr:['Atom satrancı','Her alma bir patlamadır: alan taş, alınan taş ve çevresindeki sekiz karedeki piyon dışı tüm taşlar tahtadan kalkar. Rakip şahı patlatan kazanır. Şahlar birbirine dokunabilir, çünkü şah şahı alamaz.'],
  en:['Atomic','Every capture is an explosion: the capturing piece, the captured piece and all non-pawn pieces on the eight surrounding squares are removed. Blowing up the enemy king wins. Kings may touch, since a king cannot capture.']},
 {tr:['Kaybeden kazanır (Antichess)','Alma zorunludur ve amaç bütün taşlarını kaybetmektir. Şah sıradan bir taştır, şah ve mat yoktur. Taşları kaybeden ya da hiç hamlesi kalmayan oyuncu kazanır.'],
  en:['Antichess (Losing chess)','Captures are compulsory and the goal is to lose all your pieces. The king is an ordinary piece; there is no check or mate. The player who runs out of pieces or moves wins.']},
 {tr:['Horde (Sürü)','Beyazın şahı yoktur, onun yerine 36 piyonu vardır; siyah normal taşlarla başlar. Siyah bütün piyonları alırsa, beyaz siyahı mat ederse kazanır. Piyon duvarına karşı taşların gücünü dengeleyen ilginç bir sınavdır.'],
  en:['Horde','White has no king but 36 pawns; Black has the normal army. Black wins by capturing every pawn, White by checkmating Black. A fascinating test of pieces against a wall of pawns.']},
 {tr:['Yarışan Şahlar (Racing Kings)','Tahtada piyon yoktur, iki taraf da aynı tarafta dizilir. Şah çekmek yasaktır. Şahını önce sekizinci sıraya ulaştıran kazanır.'],
  en:['Racing Kings','There are no pawns and both sides start on the same side of the board. Giving check is forbidden. The first king to reach the eighth rank wins.']},
];
